import React, { useState } from "react";
import quizData from "../data/quizData";
import "../css/Quiz.css";
import Footer from "../composant/Footer";
import Header from "../composant/Header";

const Quiz = () => {
  const [current, setCurrent] = useState(0);
  const [score, setScore] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState([]);
  const [showExplanation, setShowExplanation] = useState(false);

  const currentQuestion = quizData[current];

  if (!currentQuestion) return <div>Chargement...</div>;

  const correctIndices = Array.isArray(currentQuestion.correct_answers)
    ? currentQuestion.correct_answers
    : [currentQuestion.correct_answers];

  const allOptions = Array.isArray(currentQuestion.options)
    ? [...currentQuestion.options]
    : [];

  if (!allOptions.length) return <div>Cette question est mal configurée.</div>;

  const handleSelectChange = (e, index) => {
    const value = e.target.value;
    const newSelected = [...selectedAnswers];
    newSelected[index] = Number(value); // on garde l'index de l'option
    setSelectedAnswers(newSelected);
  };

  const handleValidate = () => {
    const selectedSet = new Set(selectedAnswers);
    const correctSet = new Set(correctIndices);

    const isCorrect =
      selectedSet.size === correctSet.size &&
      [...correctSet].every((ans) => selectedSet.has(ans));

    if (isCorrect) setScore(score + 1);
    setShowExplanation(true);
  };

  const handleNext = () => {
    setSelectedAnswers([]);
    setShowExplanation(false);
    if (current < quizData.length - 1) {
      setCurrent(current + 1);
    } else {
      alert(`Quiz terminé ! Votre score: ${score}/${quizData.length}`);
      setCurrent(0);
      setScore(0);
    }
  };

  return (
    <>
      <Header />
        <div className="quiz-beta-warning"
            style={{
                margin: "auto",
                marginBottom: "10px",
                marginTop: "1em",
                color: "orange",
                fontWeight: "bold",
                textAlign: "center",
            }}
            >
            ⚠️ Ceci est une version bêta du quiz. Certaines fonctionnalités peuvent être expérimentales et des bugs peuvent apparaître.
            </div>


      <div className="quiz-container">
        <div className="qr-hero-quiz" style={{ marginBottom: "20px" }}>
          <div className="icon">❓</div>
          <h2>Bienvenue au Quiz sur les QR Codes !</h2>
          <p className="lead">
            Testez vos connaissances sur les QR Codes, leur fonctionnement et
            leurs usages. Sélectionnez les bonnes réponses et découvrez des
            explications après chaque question.
          </p>
        </div>

        <h1>Quiz sur les QR Codes</h1>
        <div className="quiz-box">
          <div className="quiz-question">{currentQuestion.question}</div>

          <div className="quiz-answers">
            {allOptions.map((opt, index) => (
                <div key={index} className="quiz-option">
                <input
                    type="checkbox"
                    id={`answer-${index}`}
                    value={index}
                    checked={selectedAnswers.includes(index)}
                    onChange={() => {
                    if (selectedAnswers.includes(index)) {
                        setSelectedAnswers(selectedAnswers.filter((i) => i !== index));
                    } else {
                        setSelectedAnswers([...selectedAnswers, index]);
                    }
                    }}
                    style={{ display: "none" }} // cache la checkbox
                />
                <label
                    htmlFor={`answer-${index}`}
                    className={`quiz-answer-btn ${
                    selectedAnswers.includes(index) ? "selected" : ""
                    }`}
                >
                    {opt}
                </label>
                </div>
            ))}
        </div>


          {!showExplanation && (
            <button onClick={handleValidate} className="quiz-next-btn">
              Valider
            </button>
          )}

          {showExplanation && (
            <>
              <div className="quiz-explanation">{currentQuestion.explanation}</div>
              <button onClick={handleNext} className="quiz-next-btn">
                Question suivante
              </button>
            </>
          )}
        </div>
        <div className="quiz-score">Score: {score}</div>
      </div>
      <Footer />
    </>
  );
};

export default Quiz;
