import React, { useState } from 'react';
import '../css/Header.css';
import logo from "../img/logo.png";

const Header = () => {
  const [menuOpen, setMenuOpen] = useState(false);

  const toggleMenu = () => setMenuOpen(!menuOpen);

  return (
    <header className="header">
      <a href="/" className="logo-link">
        <img src={logo} alt="Prevention QR Code" className="logo" />
        <h1>PrevenQR</h1>
      </a>

      {/* Bouton hamburger */}
      <div className="menu-toggle" onClick={toggleMenu}>
        <div className={`bar ${menuOpen ? 'open' : ''}`}></div>
        <div className={`bar ${menuOpen ? 'open' : ''}`}></div>
        <div className={`bar ${menuOpen ? 'open' : ''}`}></div>
      </div>

      {/* Menu coulissant */}
      <nav className={`nav ${menuOpen ? 'open' : ''}`}>
        <a href="#features" onClick={toggleMenu}>Fonctionnalités</a>
        <a href="#about" onClick={toggleMenu}>À propos</a>
        <a href="#contact" onClick={toggleMenu}>Contact</a>
        <a href="/#quiz" onClick={toggleMenu}>Quiz</a> {/* Lien vers une autre page */}
      </nav>
    </header>
  );
};

export default Header;
